entries[1239674] = { ["name"] = "Unnachgiebiges Netherprisma", ["text"] = "100 Meter Reichweite\nSofort\nEure Fähigkeiten, die Schaden zufügen, ziehen fokussierte Leere aus dem Prisma, um ( 441 * 1 ) kosmischen Schaden zu verursachen, der zwischen Eurem Ziel und nahen Gegnern aufgeteilt wird. Der Schaden erhöht sich pro getroffenem Gegner um 30%, bis insgesamt 150%. Dieser Effekt kann alle 10 Sek. auftreten und sammelt bis zu 18 Mal die latente Macht innerhalb des Prismas." }
