entries[1239689] = { ["name"] = "Tobende Dämonenseele", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Einsatz von 'Schatten des Todes' entfesselt Eure 'Dämonenseele' 9 Sek. lang gegen Euer aktuelles Ziel, was dem Ziel (279.306% der Zaubermacht) Schattenschaden und Gegnern innerhalb von 10 Metern (186.209% der Zaubermacht) Schattenschaden zufügt." }
entries[1239691] = { ["name"] = "Schrecken des Unbekannten", ["text"] = "Kanalisiert\nDie Seelenschreiberin erfüllt markierte Spielercharaktere mit Schrecken. Nach Ablauf stößt der Spielercharakter eine Eruption aus und fügt allen Spielercharakteren innerhalb von 9 Metern um die Eruption 2424449 Arkanschaden zu.\n\nGetroffene Schicksale befallen ihren gebundenen Spielercharakter mit ' Verwundetes Schicksal '." }
