entries[1239714] = { ["name"] = "Seelenstreich", ["text"] = "Nahkampfreichweite\nSofort\nDämonologie\nDer von Eurer dämonischen Seele verursachte Schaden wird um 10% erhöht.\n\nDer Verbrauch von 'Dämonischer Kern' füttert das dämonische Wesen in Euch, das erscheint und Eurem Ziel [(240.402% der Zaubermacht) * 0.4] Schattenschaden zufügt.\n\nGebrechen\nDer von Eurer dämonischen Seele verursachte Schaden wird um 10% erhöht.\n\nDer Verbrauch von 'Nachtsturz' füttert das dämonische Wesen in Euch, das erscheint und Eurem Ziel (240.402% der Zaubermacht) Schattenschaden zufügt." }
