entries[1240865] = { ["name"] = "Vernichtender Seelenkampf", ["text"] = "Unbegrenzte Reichweite\nSofort\nSeelenbinderin Naazindhri schleudert eine Kugel in die Richtung eines zufällig ausgewählten Spielercharakters, die allen getroffenen Spielercharakteren 11250162 Arkanschaden zufügt und sie 20 Sek. lang um 15% erhöhten Schaden erleiden lässt.\n\nWird eine Bindungskammer von der Kugel getroffen, wird deren Schild zerstört und die darin befindliche ungebundene Seele erleidet um 200% erhöhten Schaden." }
