entries[1241099] = { ["name"] = "Magma", ["text"] = "100 Meter Reichweite\nSofort\nSchleudert Lava auf Gegner innerhalb von 50 Metern und fügt Gegnern innerhalb von 5 Metern um den Einschlagsort 50 Vulkanschaden zu.\n\nJeder Einschlag beschwört eine Lavakugel, die sich 6 Sek. lang auf einen Gegner fixiert und Gegnern innerhalb von 5 Metern 70 Vulkanschaden zufügt, wenn sie mit einem Gegner kollidiert." }
entries[1241100] = { ["name"] = "Mystische Peitsche", ["text"] = "Wirken in 2 sek.\nSeelenbinderin Naazindhri schlägt nach ihrem aktuellen Ziel und fügt ihm 5 Sek. lang alle 1 Sek. 6605300 Arkanschaden zu. [Der Hieb brandmarkt das Ziel und erhöht 45 Sek. lang den Schaden von 'Mystische Peitsche' um\n40% sowie den körperlichen Schaden um 15%.\n\nDieser Effekt ist stapelbar.] [Der Hieb brandmarkt das Ziel und erhöht den Schaden von 'Mystische Peitsche' um 12%.\n\nDieser Effekt ist stapelbar.]" }
