entries[1241142] = { ["name"] = "Vernichtender Beschuss", ["text"] = "Unbegrenzte Reichweite\nSofort\n' Die Plexuswache visiert einen Spielercharakter, der geläutert werden soll, an und feuert zwei Geschosse auf ihn ab. Jedes Geschoss verursacht 240 Arkanschaden, der auf alle Spielercharaktere innerhalb von 6 Metern aufgeteilt wird und sie vom Primärziel wegstößt .\n\nTrifft ein Geschoss weniger als 5 Spielercharaktere, verursacht der Effekt stattdessen 120 Arkanschaden bei allen Spielercharakteren. [] '\nWenn ' Vernichtender Beschuss ' nicht mindestens 5 Spielercharaktere trifft, fügt er stattdessen allen Spielercharakteren 120 Arkanschaden zu." }
entries[1241149] = { ["name"] = "Gesplittert", ["text"] = "300 Meter Reichweite\nSofort\nWenn ' Gehärteter Panzer ' zersplittert, ist der Bedienstete verwundbar, bis der Panzer sich neu gebildet hat." }
