entries[1241210] = { ["name"] = "Zeichen der Ketten", ["text"] = "Unbegrenzte Reichweite\nSofort\nIlyssa platziert ein Zeichen der Ketten an der Position ihres aktuellen Ziels, das sich nach (5 / 2) Sek. aktiviert.\n\nAlle Spielercharaktere werden zu seinem Zentrum hingezogen und verlangsamt, was ihre Bewegungsgeschwindigkeit für 6 Sek. um 60% verringert." }
entries[1241240] = { ["name"] = "Aufgeladener Kristall", ["text"] = "Eure Zauber und Angriffe haben eine Chance, 'Geladener Blitz' auf Euer Ziel niedergehen zu lassen, was ( 1 * 965 ) Naturschaden verursacht, aufgeteilt auf Ziele innerhalb von 8 Metern." }
entries[1241241] = { ["name"] = "Energieschild", ["text"] = "Wenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern." }
entries[1241242] = { ["name"] = "Aufgeladene Berührung", ["text"] = "Eure Heilzauber haben eine Chance, auf das Ziel mit der geringsten Gesundheit innerhalb von 40 Metern überzuspringen und es um 1766 Gesundheit zu heilen." }
entries[1241243] = { ["name"] = "Elektrische Ladung", ["text"] = "Ihr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 8 erhöht, bis maximal (12 * 8 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich." }
entries[1241244] = { ["name"] = "Geladene Blitze", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit trefft Ihr 15 Sek. lang alle 3 Sek. ein zufälliges gegnerisches Ziel innerhalb von 40 Metern und fügt ihm ( 1 * 167 ) Naturschaden zu." }
entries[1241245] = { ["name"] = "Kauterisierende Blitze", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit heilt Ihr 15 Sek. lang alle 3 Sek. den Verbündeten mit der geringsten Gesundheit innerhalb von 40 Metern um 450 Gesundheit." }
