entries[1241732] = { ["name"] = "Schwärende Sense", ["text"] = "Nahkampfreichweite\nSofort\nFührt einen eisigen Angriff aus zwei Hieben aus, der die frostige Essenz des Winters freisetzt und allen getroffenen Gegnern mit jedem Schlag (92% der Angriffskraft) Frostschaden zufügt.\n\nJeder getroffene Gegner verringert den Schaden, den Ihr dem nächsten Gegner zufügt, um 5%, bis auf maximal 40%." }
