entries[1241833] = { ["name"] = "Fraktur", ["text"] = "Unbegrenzte Reichweite\nWirken in 2.5 sek.\nIlyssa schlägt rasch auf ihr aktuelles Ziel ein, um ihm 59728781 körperlichen Schaden zuzufügen und es mit ' Zerschmetterte Seele ' zu belegen.\n\nDurch den Schlag wird die Seele des Ziels in mehrere Fragmente gespalten, die jeweils alle ' Gebrechlichkeit ' auf dem Ziel aufrechterhalten, bis ein anderer Spielercharakter das Fragment aufnimmt." }
entries[1241837] = { ["name"] = "Fraktur", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 0 sek.)\nIlyssa schlägt rasch auf ihr aktuelles Ziel ein, um ihm 59728781 körperlichen Schaden zuzufügen und es mit ' Zerschmetterte Seele ' zu belegen.\n\nDurch den Schlag wird die Seele des Ziels in mehrere Fragmente gespalten, die jeweils alle ' Gebrechlichkeit ' auf dem Ziel aufrechterhalten, bis ein anderer Spielercharakter das Fragment aufnimmt." }
entries[1241847] = { ["name"] = "Vernichtender Arkanokern", ["text"] = "Sofort\nEure Angriffe haben eine hohe Chance, den Arkanokern aufzuladen. Bei 10 Ladungen wird ein Wächter eingesetzt und überzieht Euer Ziel mit einer Arkanoexplosion. Diese verursacht ( 3596 * 1 ) Arkanschaden, der auf Gegner in der Nähe aufgeteilt wird. Stellt 2 Ladungen wieder her, wenn nur ein Gegner getroffen wird.\n\nSchaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%." }
