entries[1242220] = { ["name"] = "Hyperthermie", ["text"] = "Sofort\nWenn 'Einäschern' nicht aktiv ist, besteht beim Verbrauch von 'Kampfeshitze' eine geringe Chance, dass sämtliche Einsätze von 'Pyroschlag' und 'Flammenstoß' 5 Sek. lang Spontanzauber werden und garantiert einen kritischen Treffer erzielen.\n\nJeder Einsatz von 'Pyroschlag' oder 'Flammenstoß' erhöht den Schaden von 'Pyroschlag' oder 'Flammenstoß' um 15%, bis maximal 150%." }
