entries[1242224] = { ["name"] = "Fraktur", ["text"] = "Sofort\nIlyssa schlägt rasch auf ihr aktuelles Ziel ein, um ihm 59728781 körperlichen Schaden zuzufügen und es mit ' Zerschmetterte Seele ' zu belegen.\n\nDurch den Schlag wird die Seele des Ziels in mehrere Fragmente gespalten, die jeweils alle ' Gebrechlichkeit ' auf dem Ziel aufrechterhalten, bis ein anderer Spielercharakter das Fragment aufnimmt." }
entries[1242225] = { ["name"] = "Sturmzorn", ["text"] = "8 Meter Reichweite\nSofort\nArtefaktfähigkeit\n\nEntfesselt einen schrecklichen Sturm, der Gegnern innerhalb von 8 Metern im Verlauf von 12 Sek. [((386% Angriffs-/Zaubermacht)) * 12 / 1.5] Naturschaden zufügt.\n\nJeder getroffene Gegner verleiht Euch ' Aufziehender Sturm ', was den Schaden von ' Sturmzorn ' um 8% erhöht." }
entries[1242226] = { ["name"] = "Phasenkrümmung", ["text"] = "Sofort 1 sek. Abklingzeit\nNutzt Euren Reshiiwickel, um durch arkane Ströme zu reisen." }
entries[1242233] = { ["name"] = "Teleportationskrankheit", ["text"] = "100 Meter Reichweite\nSofort\nDie Verwendung des Portals löst kurzzeitig eine Krankheit beim Spielercharakter aus, die ihm 3 Sek. lang alle 0.5 Sek. 0 Arkanschaden zufügt." }
entries[1242237] = { ["name"] = "Arkane Überladung" }
entries[1242238] = { ["name"] = "Arkane Überladung", ["text"] = "Sofort\nArkane Energie schlägt auf den Boden ein und fügt allen Spielercharakteren innerhalb von 1.5 Metern um den Einschlagsort 15 Arkanschaden zu." }
entries[1242240] = { ["name"] = "Nostwins Ungeduld", ["text"] = "Wenn Ihr Euch nicht im Kampf befindet und Euch bewegt, erhaltet Ihr alle 4 Sek. ' Zeitläufer ', was Eure Geschwindigkeit (außer beim Fliegen) um 20% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar." }
entries[1242241] = { ["name"] = "Arkane Überladung" }
entries[1242242] = { ["name"] = "Arkane Überladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nArkane Energie schlägt auf den Boden ein und fügt allen Spielercharakteren innerhalb von 1.5 Metern um den Einschlagsort 15 Arkanschaden zu." }
entries[1242245] = { ["name"] = "Zeitläufer", ["text"] = "Sofort\nWenn Ihr Euch nicht im Kampf befindet und Euch bewegt, erhaltet Ihr alle 4 Sek. ' Zeitläufer ', was Eure Geschwindigkeit (außer beim Fliegen) um 20% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar." }
entries[1242247] = { ["name"] = "Verdrehter Kreuzzug", ["text"] = "Artefaktfähigkeit\n\nRuft für 30 Sek. einen höllischen Schreckenslord herbei, der regelmäßig ' Herrschaft des Chaos ' gegen Gegner einsetzt.\n\nHerrschaft des Chaos\nDer höllische Schreckenslord ruft höllische Meteore herbei, die Gegnern innerhalb von 8 Metern 8 Sek. lang alle 1 Sek. [(379% Angriffs-/Zaubermacht)] Chaosschaden zufügen." }
entries[1242257] = { ["name"] = "Fraktur", ["text"] = "Unbegrenzte Reichweite\nSofort\nIlyssa schlägt rasch auf ihr aktuelles Ziel ein, um ihm 59728781 körperlichen Schaden zuzufügen und es mit ' Zerschmetterte Seele ' zu belegen.\n\nDurch den Schlag wird die Seele des Ziels in mehrere Fragmente gespalten, die jeweils alle ' Gebrechlichkeit ' auf dem Ziel aufrechterhalten, bis ein anderer Spielercharakter das Fragment aufnimmt." }
entries[1242259] = { ["name"] = "Geistbombe", ["text"] = "Wirken in 3 sek.\nIlyssa explodiert und fügt allen Spielercharakteren 4216149 Feuerschaden zu und belegt sie mit ' Seelenschmettern '.\n\nIlyssa zerstört sämtliche Fragmente von ' Fraktur ', die noch verbleiben, und belegt alle Spielercharaktere mit ' Ausgestoßene Seele '." }
entries[1242265] = { ["name"] = "Schattenfellbraudieb", ["text"] = "Sofort\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben." }
entries[1242270] = { ["name"] = "Verbessertes 'Niuzao den Schwarzen Ochsen beschwören'", ["text"] = "Sofort\nSolange der Zauber aktiv ist, kann 'Niuzao den schwarzen Ochsen beschwören' ein weiteres Mal gezaubert werden, damit Niuzao gewaltig auf den Boden stampft und Gegner in der Nähe in die Luft wirbelt." }
entries[1242272] = { ["name"] = "Königliche Leerenschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein kosmischer Schrecken, der von den Grausamkeiten des Nexuskönigs verzerrt und gehärtet wurde und nun schwurgebunden in Eurem Dienst steht.\"\nQuest:\nDas Ende des Zwielichtschwurs" }
entries[1242273] = { ["name"] = "Energieexplosion", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nSchleudert ein Lichtgeschoss auf das Ziel und verursacht Arkanschaden." }
entries[1242276] = { ["name"] = "Ruf der Legion: Höllischer Inquisitor", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört einen höllischen Inquisitor aus dem Wirbelnden Nether, der Euch 10 Sek. lang im Kampf unterstützt." }
entries[1242284] = { ["name"] = "Seelenschmettern", ["text"] = "Unbegrenzte Reichweite\nSofort\n' Geistbombe ' sorgt dafür, dass Spielercharaktere die nächsten 11528983 erhaltene Heilung absorbieren." }
entries[1242303] = { ["name"] = "Windende Schneise", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn 'Windende Welle' nicht mindestens 5 Ziele trifft, schirmt Loom'ithar sich mit der zusätzlichen Seide ab und absorbiert erlittenen Schaden." }
entries[1242304] = { ["name"] = "Ausgestoßene Seele", ["text"] = "Unbegrenzte Reichweite\nSofort\n' Geistbombe ' lässt alle verbleibenden abgebrochenen Fragmente von ' Fraktur ' explodieren. Dies fügt allen Spielercharakteren 3162112 Feuerschaden und zusätzlich 20 Sek. lang alle 0.5 Sek. 1545921 Feuerschaden zu. Dieser Effekt ist stapelbar." }
entries[1242310] = { ["name"] = "Statischer Blitz", ["text"] = "300 Meter Reichweite\nSofort\nDer große Auspuff lässt Blitze herabregnen, wenn er aktiviert wird, die Spielercharakteren in einem Bereich von 0 Metern 69 Naturschaden zufügen." }
