entries[1242607] = { ["name"] = "Zeitverzerrter Obelisk der Brutalität", ["text"] = "Sofort\nDas Kanalisieren dieses Obelisken stellt Eure Gesundheit und Euer Mana wieder her und gewährt den folgenden Bonus:\n\nGabe der Brutalität :\nErhöht Euren verursachten Schaden um 5% und um zusätzlich 5% für jeden getöteten Gegner. Bis zu 10-mal stapelbar.\n\nWenn der Effekt abläuft, fügt eine Explosion Gegnern in der Nähe (100% der Zaubermacht) Feuerschaden zu, der sich für jeden zusätzlichen Stapel von ' Gabe der Brutalität ' um (100% der Zaubermacht)% erhöht." }
entries[1242609] = { ["name"] = "Zeitverzerrter Obelisk der Leere", ["text"] = "Sofort\nDas Kanalisieren dieses Obelisken stellt Eure Gesundheit und Euer Mana wieder her und gewährt den folgenden Bonus:\n\nGabe der Leere :\nEure Zauber und Fähigkeiten haben eine hohe Chance, ' Schatteneruption ' zu wirken und so Gegnern innerhalb von 10 Metern um Euer Ziel (200% der Zaubermacht) Schattenschaden zuzufügen." }
