entries[1242611] = { ["name"] = "Zeitverzerrter Obelisk des Pakts", ["text"] = "Sofort\nDas Kanalisieren dieses Obelisken stellt Eure Gesundheit und Euer Mana wieder her und gewährt den folgenden Bonus:\n\nGabe des Pakts :\nBeschwört einen unterworfenen Wichtel, der für den Zaubernden kämpft." }
