entries[1242997] = { ["name"] = "Teufelsstachel", ["text"] = "100 Meter Reichweite\nSofort\nNachdem Ihr ' Verdrehter Kreuzzug ' verwendet, wird der Zauber zu ' Teufelsstachel '.\n\nTeufelsstachel\nOpfert Euren höllischen Schreckenslord gewaltsam auf einem Teufelsstachel und fügt Gegnern innerhalb von 30 Metern [(5213% Angriffs-/Zaubermacht)] Chaosschaden zu. Getroffene Gegner werden ' Teufelsberührt '." }
entries[1243004] = { ["name"] = "Dunkelschlundwüter", ["text"] = "100 Meter Reichweite\nSofort\nGräbt sich ein und ruft Würmer herbei, die Gegner angreifen und allen Gegnern in ihrem Weg Schattenschaden zufügen. Danach graben sich die Würmer unterhalb eines zufälligen Gegners wieder ein und fügen allen Gegnern innerhalb von 10 Metern 45 körperlichen Schaden zu." }
entries[1243005] = { ["name"] = "Momentus' Beharrlichkeit", ["text"] = "Während ' Nostwins Ungeduld ' aktiv ist, ist Eure Gesundheitsregeneration um 300% erhöht." }
entries[1243006] = { ["name"] = "Modifizierter Greifhaken" }
entries[1243007] = { ["name"] = "Sandschritt", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nDer Zaubernde teleportiert zu seinem Ziel und schlitzt es auf, was ihm 139413 körperlichen Schaden zufügt. Zusätzlich hinterlässt es eine Wunde, die 6 Sek. lang alle 1.5 Sek. 26140 körperlichen Schaden verursacht." }
entries[1243008] = { ["name"] = "Momentus' Beharrlichkeit", ["text"] = "Sofort\nWährend ' Nostwins Ungeduld ' aktiv ist, ist Eure Gesundheitsregeneration um 300% erhöht." }
entries[1243010] = { ["name"] = "Ungebundener Stich", ["text"] = "40 Meter Reichweite\nWirken in 3.5 sek. 4 sek. Abklingzeit\nFeuert 3.8 Sek. lang alle 1.3 Sek. erratische Energien auf einen Gegner. Fügt Gegnern innerhalb von 0 Metern um den Einschlag Arkanschaden zu.\n\nLöst auch ' Ungebundener Fokus ' aus.\n\nUngebundener Fokus\n100 Meter Reichweite\n\nSofort Erschafft eine Kugel instabiler Arkanenergie an einer Position, die Zielen innerhalb von 5 Metern 5 Arkanschaden zufügt und sie zurückstößt.\n\nDiese Detonation kann eine Kettenreaktion auslösen." }
entries[1243017] = { ["name"] = "Sandeinschlag", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nDer Zaubernde lässt um sich herum Sand ausbrechen, der Spielercharakteren innerhalb eines Bereichs von 8 Metern 522799 Naturschaden zufügt." }
